const path = (id) => {
  if (!id) return '#';
  if (id === 'beranda') return 'index.html';
  if (typeof id === 'string' && (id.includes('.html') || id.includes('?') || id.startsWith('http') || id.startsWith('#') || id.startsWith('/'))) {
    return id;
  }
  const found = ROUTES.find(r => r[0] === id);
  if (found) return found[0] + '.html';
  return id + '.html';
};
const link=(id,label,cls='')=>`<a class="${cls?cls+' ':''}nav-link" href="${path(id)}">${label}</a>`;

